window.kbPageData["views/entry/k-0bffd37680ddf145"] = {"key":"entry/k-0bffd37680ddf145","state":{"route":"entry/k-0bffd37680ddf145"},"node":{"id":"k-0bffd37680ddf145","mode":"k","title":"混合增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["基期量均为正时，合计同比增速介于各组成部分的同比增速之间","混合增长率是以各组成部分基期量为权重的加权平均","合计增长率是以各部分基期量为权重的增速加权平均"],"qs":["国考 2024 行政执法 行测#130","江苏 2025 B类 行测#125","江苏 2025 C类 行测#120"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":3,"repeatPositions":0,"directorySummary":"各组成部分可以相加且基期量均为正时，合计同比增长率是各部分同比增长率以各自基期量为权重的加权平均。各部分增速有差异时，合计增速严格介于最低和最高增速之间。","review":{"definition":"各组成部分可以相加且基期量均为正时，合计同比增长率是各部分同比增长率以各自基期量为权重的加权平均。各部分增速有差异时，合计增速严格介于最低和最高增速之间。","explanation":"合计增速等于各部分同比增量之和除以各部分基期量之和，而每部分的同比增量等于其基期量乘以同比增速。本题中，2023年一季度机器人设备进口金额由1至2月和3月两部分相加得到。3月同比增长68.5%，高于一季度的55.1%，因此1至2月合计同比增速必低于55.1%，也低于3月，故B项正确。","references":[],"evidence":"根据混合增长率口诀“混合居中”可知","disposition":"独立词条","basis":"据原题和解析编释。","title":"混合增长率","related":[],"examFocus":{"国考 2024 行政执法 行测#130":"用混合增长率的居中关系，对照一季度累计与3月单月的机器人设备进口额同比增速，判断3月与1至2月合计增速的相对高低。","江苏 2025 B类 行测#125":"将东北、东南片区接待过夜游客人次的同比增速按各自基期人次加权，再与题设的增速上限比较。","江苏 2025 C类 行测#120":"把东北、东南片区接待过夜游客人次的同比增速按各自的基期人次加权，再与题设上限比较。"}},"readings":[{"origin":"k-0bffd37680ddf145","title":"混合增长率","qs":["国考 2024 行政执法 行测#130"],"definition":"各组成部分可以相加且基期量均为正时，合计同比增长率是各部分同比增长率以各自基期量为权重的加权平均。各部分增速有差异时，合计增速严格介于最低和最高增速之间。","explanation":"合计增速等于各部分同比增量之和除以各部分基期量之和，而每部分的同比增量等于其基期量乘以同比增速。本题中，2023年一季度机器人设备进口金额由1至2月和3月两部分相加得到。3月同比增长68.5%，高于一季度的55.1%，因此1至2月合计同比增速必低于55.1%，也低于3月，故B项正确。","evidence":"根据混合增长率口诀“混合居中”可知","doubt":"","references":[]},{"origin":"k-267cd2d2a60e35e6","title":"混合增长率","qs":["江苏 2025 C类 行测#120"],"definition":"若干可加总部分的混合增长率等于其合计增长量除以合计基期量。各部分基期量均为正时，这相当于以各部分基期量为权重，对各部分增长率求加权平均。","explanation":"各部分的增长量等于基期量乘以增长率，因此基期量越大，该部分的增长率在合计增速中的权重越大。第120题中，东北片区和东南片区的基期接待量分别为1125÷1.382≈814.04万人次和739÷1.701≈434.45万人次。两片区合计增速偏向东北片区较低的38.2%，按基期量加权约为49.30%，低于D项的54.2%，所以D项可以推出。","evidence":"混合后居中，偏向基期较大的（一般用现期量代替基期量）","doubt":"","references":[]},{"origin":"k-ac4cffaa16d463cb","title":"混合增长率","qs":["江苏 2025 B类 行测#125"],"definition":"各部分可以相加、增长时期相同且基期量均为正时，合计增长率等于各部分增长率以各自基期量为权重的加权平均。","explanation":"合计增长率等于各部分增长量之和除以基期量之和，而各部分增长量等于各自的基期量乘以增长率。题中，东北、东南片区的基期量分别为1125÷1.382≈814.04万人次和739÷1.701≈434.45万人次。用这两个基期量对38.2%和70.1%加权，得到合计增长率约49.3%，低于54.2%，所以D项可以推出。现期量可以用于粗估，本题用还原后的基期量核验上限。","evidence":"东北片区接待过夜游客1125万人次，增长38.2%；东南片区接待过夜游客739万人次，增长70.1%。","doubt":"","references":[]}]},"questions":{"国考 2024 行政执法 行测#130":{"paper":"国考 2024 行政执法 行测","n":130,"mod":"资料分析","src":["dfddc59dc6e7d9da5d71.pdf",26],"asrc":["6493f3a6a55c38431852.pdf",42],"card":"55e74a3840025574c73359e3","links":[{"id":"k-0bffd37680ddf145","role":"解题依据","why":"合计增速以各部分基期量为权重，季度增速可作为比较两段增速的中间值。"}]},"江苏 2025 B类 行测#125":{"paper":"江苏 2025 B类 行测","n":125,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",25],"asrc":["f2ff67a0f2a2f7e8e926.pdf",42],"card":"1b083be5353fe6152a453423","links":[{"id":"k-0bffd37680ddf145","role":"解题依据","why":"核验两片区合计增速的上限时，需用基期量判断合计增速偏向哪一侧。"}]},"江苏 2025 C类 行测#120":{"paper":"江苏 2025 C类 行测","n":120,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",25],"asrc":["d1de3b437151c05b769e.pdf",36],"card":"03c471d7e233eb659516e3da","links":[{"id":"k-0bffd37680ddf145","role":"解题依据","why":"核验两片区合计增速的上界时，需根据各片区基期量判断合计增速偏向哪一侧。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-0bffd37680ddf145":[["国考 2024 行政执法 行测#130"],["江苏 2025 B类 行测#125"],["江苏 2025 C类 行测#120"]]}};
